mapper.select:
SELECT jp.job_id , jp.comp_id , uc.company_name , jp.title , jp.exp_type , jp.exp_year , jp.edu , jp.emp_type , jp.address , jp.close_date , (jp.close_date < CURDATE()) AS closed , DATE_FORMAT(jp.close_date, '~ %m/%d(%a)') AS deadline_label FROM job_bookmark jb INNER JOIN JOB_POSTING jp ON jp.job_id = jb.job_id INNER JOIN USER_COMPANY uc ON uc.user_id = jp.comp_id WHERE jb.user_id = #{userId}
AND ( jp.title LIKE CONCAT('%', #{keyword}, '%') OR uc.company_name LIKE CONCAT('%', #{keyword}, '%') )
AND jp.close_date >= CURDATE()
AND jp.close_date < CURDATE()
AND NOT EXISTS ( SELECT 1 FROM JOB_APPLICATION ja WHERE ja.user_id = jb.user_id AND ja.job_id = jb.job_id )
ORDER BY jb.reg_date DESC, jb.bookmark_id DESC LIMIT #{page.offset, jdbcType=INTEGER}, #{page.safeSize, jdbcType=INTEGER}

mapper.delete:
DELETE FROM job_bookmark
WHERE user_id = #{userId}
  AND job_id  = #{jobId}

DELETE FROM job_bookmark
WHERE user_id = #{userId}
  AND job_id IN
  
    #{id}

mapper.select:
SELECT COUNT(*) FROM JOB_APPLICATION ja WHERE ja.user_id = #{userId}
AND ja.app_step NOT IN ('최종합격','최종불합격','최종발표')
AND ja.app_step IN ('최종합격','최종불합격','최종발표')

mapper.delete:
DELETE FROM JOB_APPLICATION
WHERE app_id = #{appId}
  AND user_id = #{userId}

mapper.select:
SELECT r.job_id , r.score , jp.title , jp.field , jp.address , jp.open_date , jp.close_date FROM RECOMMENDED_JOB r JOIN JOB_POSTING jp ON jp.job_id = r.job_id
LEFT JOIN JOB_APPLICATION ja2 ON ja2.job_id = jp.job_id AND ja2.user_id = #{userId}
ORDER BY jp.close_date ASC, r.score DESC
ORDER BY jp.open_date DESC, r.score DESC
ORDER BY r.score DESC, r.recommended_at DESC
LIMIT #{page.offset, jdbcType=INTEGER}, #{page.safeSize, jdbcType=INTEGER}

mapper.update:
UPDATE RECOMMENDED_JOB
SET is_active = 0
WHERE person_user_id = #{userId}
  AND job_id = #{jobId}

